import json, math
p='osm_amenity_school.geojson'
with open(p) as f: d=json.load(f)
lat0,lon0=41.9231,-87.7093
R=3958.7613

def hav(lat,lon):
    a=math.radians(lat-lat0); b=math.radians(lon-lon0)
    x=math.sin(a/2)**2+math.cos(math.radians(lat0))*math.cos(math.radians(lat))*math.sin(b/2)**2
    return 2*R*math.asin(math.sqrt(x))
rows=[]
for ft in d['features']:
    g=ft['geometry']; c=g['coordinates']
    if g['type']=='Point': lon,lat=c
    else:
        pts=[]
        def rec(x):
            if isinstance(x[0],(int,float)): pts.append(x)
            else:
                for y in x: rec(y)
        rec(c); lon=sum(x[0] for x in pts)/len(pts); lat=sum(x[1] for x in pts)/len(pts)
    dist=hav(lat,lon)
    if dist<=1: rows.append((dist,ft['properties'].get('name','(unnamed)')))
print('count',len(rows))
for x in sorted(rows): print(f'{x[0]:.3f} mi\t{x[1]}')

