import json

def osm_to_geojson(raw_path, out_path):
    with open(raw_path) as f:
        data = json.load(f)
    feats = []
    for el in data.get("elements", []):
        geom = None
        if el["type"] == "node":
            geom = {"type":"Point","coordinates":[el["lon"],el["lat"]]}
        elif el["type"] == "way":
            coords = [[p["lon"],p["lat"]] for p in el.get("geometry",[])]
            if len(coords) >= 4 and coords[0]==coords[-1]:
                geom = {"type":"Polygon","coordinates":[coords]}
            elif len(coords) >= 2:
                geom = {"type":"LineString","coordinates":coords}
        if geom is None:
            continue
        props = dict(el.get("tags",{}))
        props["osm_type"]=el["type"]; props["osm_id"]=el["id"]
        feats.append({"type":"Feature","geometry":geom,"properties":props})
    gj = {"type":"FeatureCollection","features":feats}
    with open(out_path,"w") as f:
        json.dump(gj,f)
    return len(feats)

n_roads = osm_to_geojson("roads_raw.json","roads.geojson")
n_build = osm_to_geojson("buildings_raw.json","buildings.geojson")
print("roads features:", n_roads)
print("buildings features:", n_build)

# Check road types
with open("roads.geojson") as f:
    rj = json.load(f)
from collections import Counter
c = Counter(f["properties"].get("highway") for f in rj["features"])
print("road highway types:", dict(c))

